changeSet.sql:
CREATE MATERIALIZED VIEW mv_daily_recon_summary AS SELECT t.trade_date, cp.region, i.asset_class, COUNT(*) AS total_trades, COUNT(*) FILTER (WHERE t.status = 'MATCHED') AS matched_trades, COUNT(*) FILTER (WHERE t.status IN ('UNMATCHED', 'DISPUTED')) AS open_breaks, ROUND(COALESCE(SUM(t.quantity * t.price), 0)::NUMERIC, 2) AS gross_notional, ROUND( ( COUNT(*) FILTER (WHERE t.status = 'MATCHED')::NUMERIC / NULLIF(COUNT(*), 0) ) * 100, 2 ) AS match_rate_pct FROM trades t JOIN counterparties cp ON cp.id = t.counterparty_id JOIN instruments i ON i.id = t.instrument_id WHERE t.deleted_at IS NULL GROUP BY t.trade_date, cp.region, i.asset_class WITH NO DATA;
CREATE UNIQUE INDEX uq_mv_daily_recon_summary ON mv_daily_recon_summary (trade_date, region, asset_class);
CREATE INDEX idx_mv_daily_recon_summary_trade_date ON mv_daily_recon_summary (trade_date);
CREATE INDEX idx_mv_daily_recon_summary_region ON mv_daily_recon_summary (region);
